create or replace function public.subdivision_list_draft_lot_inventory_events(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text) returns table(event_id uuid,inventory_state_id uuid,from_phase public.subdivision_lot_inventory_phase,to_phase public.subdivision_lot_inventory_phase,created_at timestamptz) language plpgsql security definer set search_path='' as $$ begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);return query select e.id,e.inventory_state_id,e.from_phase,e.to_phase,e.created_at from public.subdivision_lot_inventory_events e join public.subdivision_lot_inventory_states s on s.id=e.inventory_state_id and s.organization_id=e.organization_id join public.subdivision_lots l on l.id=s.lot_id and l.organization_id=s.organization_id where e.organization_id=p_organization_id and l.state='draft' order by e.created_at desc;end;$$;revoke all on function public.subdivision_list_draft_lot_inventory_events(uuid,uuid,public.operating_module,text) from public,anon,authenticated;grant execute on function public.subdivision_list_draft_lot_inventory_events(uuid,uuid,public.operating_module,text) to service_role;
